"use strict";
const path = require("path");
const dep = require("linkdep");
const part = require("./lib/part");
// Through the link beside this package, by a relative path.
const direct = require("../linkdep/extra");
const store = path.resolve(__dirname, "..", "..", "..");
exports.report = () =>
  [
    part.name,
    dep.name,
    direct.name,
    direct === dep.extra,
    path.relative(store, __filename),
    path.relative(store, direct.file),
  ].join(" ");
